export { Source } from './Source';
export type { SourceProps } from './Source';
export { Sources } from './Sources';
export type { SourcesProps } from './Sources';

import * as React from 'react';
import { cn } from '@/lib/utils';
import type { SourceItem } from '../../types';

export interface SourceProps {
  source: SourceItem;
  /**
   * 1-based citation marker rendered as a `[n]` prefix.
   * Omit to render the citation without numbering.
   */
  index?: number;
  className?: string;
}

const Source = React.forwardRef<HTMLDivElement, SourceProps>(
  ({ source, index, className, ...props }, ref) => {
    return (
      <div ref={ref} className={cn('flex gap-2 items-start text-sm', className)} {...props}>
        {index !== undefined && (
          <span className="text-muted-foreground select-none" aria-hidden="true">
            [{index}]
          </span>
        )}
        <div className="flex-1 min-w-0">
          <div className="font-medium text-foreground">
            {source.url ? (
              <a
                href={source.url}
                target="_blank"
                rel="noopener noreferrer"
                className="hover:text-primary transition-colors"
              >
                {source.title}
              </a>
            ) : (
              <span>{source.title}</span>
            )}
          </div>
          {source.snippet && (
            <div className="text-xs text-muted-foreground mt-1 line-clamp-2">
              {source.snippet}
            </div>
          )}
        </div>
      </div>
    );
  }
);
Source.displayName = 'Source';

export { Source };

import * as React from 'react';
import { cn } from '@/lib/utils';
import type { SourceItem } from '../../types';
import { Source } from './Source';

export interface SourcesProps {
  sources: SourceItem[];
  className?: string;
  maxDisplay?: number;
  /** Heading label; override for localization. */
  label?: string;
}

const Sources = React.forwardRef<HTMLDivElement, SourcesProps>(
  ({ sources, className, maxDisplay = 3, label = 'Sources', ...props }, ref) => {
    const displaySources = maxDisplay ? sources.slice(0, maxDisplay) : sources;
    const hasMore = maxDisplay && sources.length > maxDisplay;

    if (sources.length === 0) {
      return null;
    }

    return (
      <div ref={ref} className={cn('mt-4 pt-4 border-t border-border', className)} {...props}>
        <div className="text-xs font-medium text-muted-foreground mb-2">{label}</div>
        <div className="space-y-2">
          {displaySources.map((source, index) => (
            <Source key={source.id} source={source} index={index + 1} />
          ))}
          {hasMore && (
            <div className="text-xs text-muted-foreground">
              +{sources.length - (maxDisplay ?? 0)} more sources
            </div>
          )}
        </div>
      </div>
    );
  }
);
Sources.displayName = 'Sources';

export { Sources };

{
  "id": "source",
  "name": "Source / Sources",
  "tier": "molecule",
  "description": "Displays citations and references for an AI response. `Source` renders a single citation; `Sources` renders a numbered list with an overflow count.",
  "designIntent": "Make generated answers transparent by showing where information came from.",
  "props": [
    {
      "name": "index",
      "type": "number",
      "required": false,
      "description": "1-based citation marker rendered as [n]; omit on Source to hide numbering."
    },
    {
      "name": "source",
      "type": "SourceItem",
      "required": true,
      "description": "The single source to render (Source component)"
    },
    {
      "name": "onSelect",
      "type": "(source: SourceItem) => void",
      "required": false,
      "description": "Called when the source chip is clicked"
    },
    {
      "name": "sources",
      "type": "SourceItem[]",
      "required": true,
      "description": "List of sources to render (Sources component)"
    },
    {
      "name": "maxDisplay",
      "type": "number",
      "defaultValue": "3",
      "required": false,
      "description": "Maximum number of source chips to show before collapsing (Sources component)"
    },
    {
      "name": "label",
      "type": "string",
      "defaultValue": "Sources",
      "required": false,
      "description": "Section label above the source list (Sources component)"
    }
  ],
  "examples": [
    {
      "title": "Citations list",
      "code": "<Sources sources={[{ id: '1', title: 'React docs', url: 'https://react.dev' }, { id: '2', title: 'MDN', url: 'https://developer.mozilla.org' }]} />"
    },
    {
      "title": "Single inline citation",
      "code": "<Source source={{ id: '1', title: 'React docs', url: 'https://react.dev' }} index={1} />"
    }
  ],
  "antiPatterns": [
    {
      "title": "Do not nest Sources inside Sources",
      "explanation": "Sources is a list container; compose individual Source items only when building a custom layout."
    }
  ],
  "accessibility": [
    {
      "feature": "Link semantics",
      "implementation": "References use native links with rel=noopener when URLs are provided."
    },
    {
      "feature": "Decorative markers",
      "implementation": "[n] citation markers are aria-hidden; titles are read as link text."
    }
  ],
  "package": "@slipstream-ui/ai",
  "importPath": "@slipstream-ui/ai",
  "version": "0.0.1",
  "sourceDir": "source",
  "exportName": "Source"
}
